pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testRegression_property() public {
        c.AdjustDifficulty(1);
        uint256 diff = c.currentDifficulty();
        assertTrue(diff == 1);
    }
